import * as THREE from 'three';
import { createScene } from './data/object.js';
import * as fs from 'fs';

// Create the scene
const scene = createScene();

// Collect all geometries from the scene
const geometries = [];
const meshes = [];

scene.traverse((node) => {
  if (node.isMesh) {
    meshes.push(node);
  }
});

// Function to apply -90 degree X-rotation to vertices
function applyXRotation(geometry, mesh) {
  const positions = geometry.attributes.position.array;
  const rotationMatrix = new THREE.Matrix4();
  rotationMatrix.makeRotationX(-Math.PI / 2); // -90 degrees

  // Create world matrix: mesh transforms + rotation
  const worldMatrix = new THREE.Matrix4();
  mesh.updateMatrixWorld(true);
  worldMatrix.multiplyMatrices(rotationMatrix, mesh.matrixWorld);

  // Transform all vertices
  const vertex = new THREE.Vector3();
  for (let i = 0; i < positions.length; i += 3) {
    vertex.set(positions[i], positions[i + 1], positions[i + 2]);
    vertex.applyMatrix4(worldMatrix);
    positions[i] = vertex.x;
    positions[i + 1] = vertex.y;
    positions[i + 2] = vertex.z;
  }

  geometry.attributes.position.needsUpdate = true;
  geometry.computeBoundingBox();
  return geometry;
}

// Process all meshes and collect geometries
for (const mesh of meshes) {
  let geometry = mesh.geometry;

  if (geometry.isBufferGeometry) {
    // Clone geometry to avoid modifying original
    const clonedGeometry = geometry.clone();

    // Ensure position attribute exists
    if (!clonedGeometry.attributes.position) {
      continue;
    }

    // Apply transformation
    applyXRotation(clonedGeometry, mesh);
    geometries.push(clonedGeometry);
  }
}

// Merge all geometries
const mergedGeometry = new THREE.BufferGeometry();
if (geometries.length > 0) {
  mergedGeometry = THREE.BufferGeometry.prototype.merge.call(
    mergedGeometry,
    geometries
  );
}

// Alternative: manually merge if BufferGeometry.merge is not available
if (geometries.length > 0) {
  const positions = [];
  const indices = [];
  let vertexOffset = 0;

  for (const geom of geometries) {
    const pos = geom.attributes.position.array;
    const idx = geom.index ? geom.index.array : null;

    // Add vertices
    for (let i = 0; i < pos.length; i++) {
      positions.push(pos[i]);
    }

    // Add indices or create them
    if (idx) {
      for (let i = 0; i < idx.length; i++) {
        indices.push(idx[i] + vertexOffset);
      }
    } else {
      for (let i = 0; i < pos.length / 3; i++) {
        indices.push(i + vertexOffset);
      }
    }

    vertexOffset += pos.length / 3;
  }

  mergedGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
  if (indices.length > 0) {
    mergedGeometry.setIndex(new THREE.BufferAttribute(new Uint32Array(indices), 1));
  }
}

// Export to OBJ format
function geometryToOBJ(geometry) {
  const positions = geometry.attributes.position.array;
  const indices = geometry.index ? geometry.index.array : null;

  let obj = '# Desk Globe\n';
  obj += '# Converted from Three.js with -90 degree X-rotation for Blender Z-up\n\n';

  // Write vertices
  for (let i = 0; i < positions.length; i += 3) {
    obj += `v ${positions[i].toFixed(6)} ${positions[i + 1].toFixed(6)} ${positions[i + 2].toFixed(6)}\n`;
  }

  obj += '\n';

  // Write faces
  if (indices) {
    for (let i = 0; i < indices.length; i += 3) {
      const a = indices[i] + 1;
      const b = indices[i + 1] + 1;
      const c = indices[i + 2] + 1;
      obj += `f ${a} ${b} ${c}\n`;
    }
  } else {
    // If no indices, create faces from vertices
    const vertexCount = positions.length / 3;
    for (let i = 0; i < vertexCount; i += 3) {
      const a = i + 1;
      const b = i + 2;
      const c = i + 3;
      if (c <= vertexCount) {
        obj += `f ${a} ${b} ${c}\n`;
      }
    }
  }

  return obj;
}

const objContent = geometryToOBJ(mergedGeometry);
fs.writeFileSync('/root/output/object.obj', objContent);

console.log('Successfully exported to /root/output/object.obj');
console.log(`Total vertices: ${mergedGeometry.attributes.position.array.length / 3}`);
if (mergedGeometry.index) {
  console.log(`Total faces: ${mergedGeometry.index.array.length / 3}`);
}
EOF
